{
  "constraints": [
    {
      "constraint": "画面主体必须可识别为轨道列车（火车）或其车厢内部，而不是飞机、汽车、船舶等非轨道交通工具。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "不得出现蒸汽机车或柴油机车特有的烟囱、煤水车、明显排气烟等非电力牵引特征。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "若画面呈现TGV动力车头，车头轮廓应为高速列车常见的流线型或楔形，不得画成方正的普通货运机车或通勤机车式车头。",
      "polarity": "must_not_have",
      "variants": [
        "TGV Sud-Est、Atlantique、Réseau、Duplex、POS、Euroduplex、TGV M等型号车头细节不同，但均保持高速列车流线型或楔形轮廓"
      ],
      "source": "common_sense"
    }
  ]
}
